reference_solution:
predicate Sorted(a: seq<int>)
{
  forall i, j :: 0 <= i < j < |a| ==> a[i] <= a[j]
}

method BinarySearch(a: seq<int>, key: int) returns (index: int)
  requires Sorted(a)
  ensures 0 <= index < |a| ==> a[index] == key
  ensures index == -1 ==> forall k :: 0 <= k < |a| ==> a[k] != key
{
  var lo, hi := 0, |a|;
  while lo < hi
    invariant 0 <= lo <= hi <= |a|
    invariant forall k :: 0 <= k < lo ==> a[k] != key
    invariant forall k :: hi <= k < |a| ==> a[k] != key
  {
    var mid := (lo + hi) / 2;
    if a[mid] < key {
      lo := mid + 1;
    } else if a[mid] > key {
      hi := mid;
    } else {
      index := mid;
      return;
    }
  }
  index := -1;
}

